  const trialId = await fs.readFile(TRIAL_ID_PATH, "utf8");
  return trialId.trim();
};

const getHeaderValue = (headers: Array<{ name?: string; value?: string }>, headerName: string) => {
  const match = headers.find((header) => header.name?.toLowerCase() === headerName.toLowerCase());
  return match?.value ?? "(no subject)";
};

const main = async () => {
  if (!process.env.COMPOSIO_API_KEY) {
    throw new Error("COMPOSIO_API_KEY is required in the environment");
  }
  if (!process.env.OPENAI_API_KEY) {
    throw new Error("OPENAI_API_KEY is required in the environment");
  }

  const trialId = await getTrialId();
  const channel = `summary-${trialId}`;

  const openaiClient = new OpenAI({ apiKey: process.env.OPENAI_API_KEY });
  const composio = new Composio({
    apiKey: process.env.COMPOSIO_API_KEY,
    provider: new OpenAIProvider({ openai: openaiClient }),
  });

  const session = await composio.createSession({ entityId: USER_ID });

  const listResult = await session.execute("GMAIL_LIST_MESSAGES", {
    user_id: "me",
    max_results: 5,
  });

  const messages =
    listResult?.messages ?? listResult?.data?.messages ?? listResult?.data?.messages?.data ?? [];

  const subjects: string[] = [];

  for (const message of messages) {
    if (!message?.id) {
      continue;
    }

    const messageResult = await session.execute("GMAIL_GET_MESSAGE", {
      user_id: "me",
      message_id: message.id,
      format: "metadata",
      metadata_headers: ["Subject"],
    });

    const headers =
      messageResult?.payload?.headers ??
      messageResult?.data?.payload?.headers ??
      messageResult?.data?.payload?.headers ??
      [];

    subjects.push(getHeaderValue(headers, "Subject"));
  }

  const summaryLines = subjects.length
    ? subjects.map((subject, index) => `${index + 1}. ${subject}`)
    : ["No recent email subjects found."];

  const summary = `Here are the latest Gmail subjects for ${USER_ID}:
${summaryLines.join("\n")}`;

  await session.execute("SLACK_CHAT_POST_MESSAGE", {
    channel,
    text: summary,
  });

  console.log(`Posted summary to Slack channel ${channel}.`);
};

main().catch((error) => {
  console.error("Failed to post Gmail summary:", error);
  process.exit(1);
});
